// Lee cada issue de proyecto y cuenta lo que marcó el equipo en el formulario (proyectos/.github/ISSUE_TEMPLATE/proyecto.yml).
// GitHub arma el cuerpo del issue con una sección «### <pregunta>» por campo: las casillas quedan como «- [X] opción»
// y lo elegido en una lista desplegable, como texto (si se eligen varias, separadas por coma).
const normalizar = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

function secciones(cuerpo) {
  const out = {};
  const partes = String(cuerpo ?? '').replace(/\r\n/g, '\n').split(/^###[ \t]+(.+?)[ \t]*$/m);
  for (let i = 1; i < partes.length; i += 2) {
    const valor = (partes[i + 1] ?? '').trim();
    out[normalizar(partes[i])] = valor === '_No response_' ? '' : valor;
  }
  return out;
}
// Primero busca el título exacto (sin tildes y en minúsculas) y, si no está, el primero que lo contenga.
const seccion = (s, clave) => s[clave] ?? Object.entries(s).find(([titulo]) => titulo.includes(clave))?.[1] ?? '';
const marcadas = (texto) => [...String(texto).matchAll(/^\s*[-*]\s*\[[xX]\]\s*(.+?)\s*$/gm)].map((m) => normalizar(m[1]));

// Qué casilla cuenta para cada número (se compara sin tildes y en minúsculas)
const TECNOLOGIAS = {
  n8n: (o) => o === 'n8n',
  ia: (o) => /^ia\b/.test(o),
  supabase: (o) => o.includes('supabase'),
  clerk: (o) => o.includes('clerk'),
  avalanche_fuji: (o) => o.includes('avalanche') || o.includes('fuji'),
  google_cloud: (o) => o.includes('google cloud'),
};
// La línea: una lista desplegable obligatoria, una por equipo. Un issue registrado antes de que el formulario
// la pidiera queda en «sin_linea».
const LINEAS = {
  ia: (o) => o.startsWith('ia para'),
  web3: (o) => o.includes('web3'),
  apps: (o) => o.includes('apps con login'),
  impacto: (o) => o.includes('impacto'),
};
const NOMBRE_LINEA = { ia: 'IA para tu comunidad', web3: 'Web3 con Avalanche Fuji', apps: 'Apps con login y datos', impacto: 'Impacto social y ambiental' };
// Las menciones especiales a las que se postula el equipo (casillas opcionales: una, las dos o ninguna).
const MENCIONES = {
  avalanche_fuji: (o) => o.includes('avalanche') || o.includes('fuji'),
  google_cloud: (o) => o.includes('google cloud'),
};
const NOMBRE_MENCION = { avalanche_fuji: 'Mejor uso de Avalanche Fuji', google_cloud: 'Mejor uso de Google Cloud' };
const ECOSISTEMA = {
  core_wallet: (o) => o.includes('core wallet'),
  avalanche_academy: (o) => o.includes('academy'),
  team1_latam: (o) => o.includes('team1'),
};
const PARTIERON_DE = {
  fundamentos: (o) => o.includes('fundamentos'),
  ia: (o) => o === 'ia',
  avalanche_fuji: (o) => o.includes('avalanche'),
  clerk: (o) => o.includes('clerk'),
  supabase: (o) => o.includes('supabase'),
  proyectos_completos: (o) => o.includes('proyectos completos'),
  google_cloud: (o) => o.includes('google cloud'),
  casos_de_uso: (o) => o.includes('casos de uso'),
  desde_cero: (o) => o.includes('desde cero'),
};
const contar = (reglas, elegidas) => Object.fromEntries(Object.entries(reglas).map(([k, f]) => [k, elegidas.some(f) ? 1 : 0]));
const sumar = (lista) => lista.reduce((a, b) => Object.fromEntries(Object.keys(b).map((k) => [k, (a[k] ?? 0) + b[k]])), {});

// Los issues abiertos con la etiqueta (la API también devuelve pull requests: se descartan)
const issues = $input.all().map((i) => i.json).filter((i) => i.number && !i.pull_request);

const fichas = issues.map((issue) => {
  const s = secciones(issue.body);
  const opcionesBase = seccion(s, 'partieron').split(',').map(normalizar).filter(Boolean);
  const hash = (seccion(s, 'hash').match(/0x[0-9a-fA-F]{64}/) ?? [])[0]?.toLowerCase() ?? null;
  const opcionLinea = normalizar(seccion(s, 'linea'));
  const linea = Object.keys(LINEAS).find((k) => LINEAS[k](opcionLinea)) ?? null;
  return {
    numero: issue.number,
    nombre: seccion(s, 'nombre del proyecto') || String(issue.title ?? '').replace(/^\s*\[proyecto\]\s*/i, ''),
    equipo: seccion(s, 'nombre del equipo'),
    url: issue.html_url,
    tecnologias: contar(TECNOLOGIAS, marcadas(seccion(s, 'tecnolog'))),
    linea,
    menciones: contar(MENCIONES, marcadas(seccion(s, 'mencion'))),
    ecosistema: contar(ECOSISTEMA, marcadas(seccion(s, 'ecosistema'))),
    partieron_de: contar(PARTIERON_DE, opcionesBase),
    hash,
  };
});

// Un hash cuenta una vez aunque lo informen dos equipos
const hashes = [];
for (const f of fichas.filter((f) => f.hash)) {
  const previo = hashes.find((h) => h.hash === f.hash);
  if (previo) previo.proyectos.push(f.numero);
  else hashes.push({ hash: f.hash, proyectos: [f.numero] });
}

return [{
  json: {
    proyectos: fichas.length,
    tecnologias: sumar([contar(TECNOLOGIAS, []), ...fichas.map((f) => f.tecnologias)]),
    lineas: {
      ...Object.fromEntries(Object.keys(LINEAS).map((k) => [k, fichas.filter((f) => f.linea === k).length])),
      sin_linea: fichas.filter((f) => !f.linea).length,
    },
    menciones: sumar([contar(MENCIONES, []), ...fichas.map((f) => f.menciones)]),
    ecosistema: sumar([contar(ECOSISTEMA, []), ...fichas.map((f) => f.ecosistema)]),
    partieron_de: sumar([contar(PARTIERON_DE, []), ...fichas.map((f) => f.partieron_de)]),
    hashes,
    lista: fichas.map((f) => ({
      numero: f.numero,
      nombre: f.nombre,
      equipo: f.equipo,
      linea: f.linea ? NOMBRE_LINEA[f.linea] : null,
      tecnologias: Object.keys(f.tecnologias).filter((k) => f.tecnologias[k]),
      menciones: Object.keys(f.menciones).filter((k) => f.menciones[k]).map((k) => NOMBRE_MENCION[k]),
      url: f.url,
    })),
  },
}];

// Un pedido por repo y por dato: visitas (views) y clones.
const c = $('Configuración').first().json;
return String(c.repos_trafico)
  .split(',')
  .map((r) => r.trim())
  .filter(Boolean)
  .flatMap((repo) => ['views', 'clones'].map((tipo) => ({ json: { repo, tipo } })));

// Junta cada respuesta con su pedido (salen en el mismo orden) y suma los totales.
const pedidos = $('Armar pedidos de tráfico').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const porRepo = {};
pedidos.forEach(({ repo, tipo }, i) => {
  const r = respuestas[i] ?? {};
  const fila = (porRepo[repo] ??= { repo, visitas: null, visitas_unicas: null, clones: null, clones_unicos: null, nota: null });
  if (r.statusCode === 200 && r.body) {
    if (tipo === 'views') Object.assign(fila, { visitas: r.body.count, visitas_unicas: r.body.uniques });
    else Object.assign(fila, { clones: r.body.count, clones_unicos: r.body.uniques });
  } else {
    fila.nota = `Sin acceso al tráfico (HTTP ${r.statusCode ?? 'sin respuesta'}): el token necesita permiso de escritura (Administration) en este repo.`;
  }
});
const trafico = Object.values(porRepo);
const suma = (campo) => trafico.reduce((a, f) => a + (f[campo] ?? 0), 0);
return [{
  json: {
    trafico,
    repos_con_acceso: trafico.filter((f) => f.visitas !== null).length,
    totales: { visitas: suma('visitas'), visitas_unicas: suma('visitas_unicas'), clones: suma('clones'), clones_unicos: suma('clones_unicos') },
  },
}];

// Junta todo: proyectos, tráfico y hashes verificados, y arma los textos para cada aliado.
const p = $('Contar proyectos').first().json;
const t = $('Resumir tráfico').first().json;
const verifico = $('Verificar hash en Fuji').isExecuted;
const recibos = verifico ? $('Verificar hash en Fuji').all().map((i) => i.json) : [];

const hashes = p.hashes.map((h, i) => {
  const r = recibos[i];
  let estado = 'sin verificar';
  if (r?.error) estado = 'error del RPC';
  else if (r && !r.result) estado = 'no existe en Fuji';
  else if (r?.result) estado = r.result.status === '0x1' ? 'salió bien' : 'falló';
  return {
    ...h,
    estado,
    bloque: r?.result?.blockNumber ? Number(BigInt(r.result.blockNumber)) : null,
    explorador: `https://build.avax.network/explorer/fuji/c-chain/tx/${h.hash}`,
  };
});
const verificados = hashes.filter((h) => h.estado === 'salió bien').length;

const n = p.proyectos;
const tr = t.totales;
const sinAcceso = t.trafico.filter((f) => f.visitas === null).map((f) => f.repo);
const trafico = t.repos_con_acceso
  ? `Repos del evento en GitHub, últimos 14 días: ${tr.visitas} visitas (${tr.visitas_unicas} únicas) y ${tr.clones} clones (${tr.clones_unicos} únicos).` +
    (sinAcceso.length ? ` Sin acceso al tráfico de: ${sinAcceso.join(', ')}.` : '')
  : 'Tráfico de los repos: no se pudo leer, el token no tiene permiso de escritura en ellos.';
const fecha = $now.setZone('America/La_Paz').toFormat('dd/MM/yyyy HH:mm');
const L = p.lineas;
const porLinea =
  `IA para tu comunidad ${L.ia} · Web3 con Avalanche Fuji ${L.web3} · Apps con login y datos ${L.apps} · Impacto social y ambiental ${L.impacto}` +
  (L.sin_linea ? ` · sin línea elegida ${L.sin_linea}` : '');
const encabezado = [
  'Nodo Cero – Hackathon n8n Bolivia · 21 de noviembre de 2026 · Santa Cruz de la Sierra.',
  'La hackathon de la comunidad n8n en Bolivia, enfocada en mujeres, de la mano de Women Techmakers Santa Cruz.',
  `Datos al ${fecha} (hora de Bolivia).`,
].join('\n');

const textos = {
  texto_team1: [
    encabezado,
    '',
    'Track Avalanche Fuji',
    `- Proyectos registrados que usan Avalanche Fuji: ${p.tecnologias.avalanche_fuji} de ${n}.`,
    `- Equipos en la línea Web3 con Avalanche Fuji: ${L.web3} de ${n}.`,
    `- Equipos que se postulan a la mención especial Mejor uso de Avalanche Fuji: ${p.menciones.avalanche_fuji}.`,
    `- Hashes de transacciones informados: ${hashes.length}. Verificados en la red Fuji: ${verificados}.`,
    `- Equipos que partieron de los workflows de Avalanche: ${p.partieron_de.avalanche_fuji}.`,
    `- Equipos que instalaron Core Wallet: ${p.ecosistema.core_wallet}.`,
    `- Equipos que se inscribieron en Avalanche Academy: ${p.ecosistema.avalanche_academy}.`,
    `- Equipos que se sumaron a Team1 LATAM: ${p.ecosistema.team1_latam}.`,
    '(Core Wallet, Academy y Team1 LATAM: lo que marcaron los equipos en el formulario.)',
    '',
    trafico,
  ].join('\n'),
  texto_supabase: [
    encabezado,
    '',
    `- Proyectos registrados que usan Supabase: ${p.tecnologias.supabase} de ${n}.`,
    `- Equipos en la línea Apps con login y datos (Clerk, Supabase y n8n): ${L.apps} de ${n}.`,
    `- Equipos que partieron de los workflows de Supabase: ${p.partieron_de.supabase}.`,
    '',
    trafico,
  ].join('\n'),
  texto_clerk: [
    encabezado,
    '',
    `- Proyectos registrados que usan Clerk: ${p.tecnologias.clerk} de ${n}.`,
    `- Equipos en la línea Apps con login y datos (Clerk, Supabase y n8n): ${L.apps} de ${n}.`,
    `- Equipos que partieron de los workflows de Clerk: ${p.partieron_de.clerk}.`,
    '',
    trafico,
  ].join('\n'),
  texto_general: [
    encabezado,
    '',
    `- Proyectos registrados: ${n}.`,
    `- Por tecnología: n8n ${p.tecnologias.n8n} · IA ${p.tecnologias.ia} · Supabase ${p.tecnologias.supabase} · Clerk ${p.tecnologias.clerk} · Avalanche Fuji ${p.tecnologias.avalanche_fuji} · Google Cloud ${p.tecnologias.google_cloud}.`,
    `- Por línea: ${porLinea}.`,
    `- Postulaciones a las menciones especiales: Mejor uso de Avalanche Fuji ${p.menciones.avalanche_fuji} · Mejor uso de Google Cloud ${p.menciones.google_cloud}.`,
    `- Hashes de Fuji verificados: ${verificados} de ${hashes.length}.`,
    '',
    trafico,
  ].join('\n'),
};

return [{ json: { ...p, ...t, hashes, hashes_informados: hashes.length, hashes_verificados: verificados, ...textos } }];
